            Q('i3', L('Dove funziona Microsoft 365 Copilot?', 'Where does Microsoft 365 Copilot work?'), [L('Dentro Word, Excel, PowerPoint, Outlook e Teams', 'Inside Word, Excel, PowerPoint, Outlook and Teams'), L('Solo nel browser', 'Only in the browser'), L('Solo su Mac', 'Only on Mac'), L('Solo nei giochi', 'Only in games')], 0, L('Nelle app di ogni giorno.', 'In everyday apps.')),
