            Q('t3', L('Che cosa dichiara la protezione dei dati aziendali?', 'What does enterprise data protection state?'), [L('I dati non addestrano i modelli di base', 'Data does not train the foundation models'), L('I dati sono pubblici', 'Data is public'), L('Nessuna regola', 'No rules'), L('I dati vanno a terzi', 'Data goes to third parties')], 0, L('Per i clienti aziendali.', 'For business customers.')),
